hudson.tasks.Shell.command:
#!/bin/sh set -eux
JENKINS_HOME=/var/jenkins_home BACKUP_DIR=$JENKINS_HOME/local_backup HOST_DATA_DIR=${HOST_DATA_PATH}/${DATA_SRC_FOLDER} # docker container run -d -u root --name jenkins -p 8080:8080 -p 50000:50000 -e JAVA_OPTS="-Duser.timezone=Asia/Taipei" -v C:\docker\jenkins_data:/var/jenkins_home -v /var/run/docker.sock:/var/run/docker.sock everett6802/jenkins:2.2 # Jenkins mount the folder in the local host: C:\docker\jenkins_data HOST_BACKUP_DIR="/host_mnt/c/docker/jenkins_data/local_backup" #HOST_BACKUP_DIR=${HOST_DATA_PATH} LOCAL=Asia/Taipei DATE=$(TZ=$LOCAL date +%Y%m%d_%H%M) ARCHIVE=data_source_backup_$DATE.tar.gz ARCHIVE_PATH=$BACKUP_DIR/$ARCHIVE KEEP=${KEEP_COUNT}
mkdir -p "$BACKUP_DIR" #cd $JENKINS_HOME # -C /data . => 只把 /data 裡面的內容打包，而不是把 /data 這個目錄本身包進去。 docker container run --rm -v "${HOST_DATA_DIR}:/data" -v "${HOST_BACKUP_DIR}:/backup" alpine:3.18 tar -czf "/backup/${ARCHIVE}" -C /data . echo "Backup created: $ARCHIVE_PATH" # The tar file exists in the 'jenkins space' # ===== 驗證備份檔（tar test）===== tar -tzf "$ARCHIVE_PATH" > /dev/null echo "Backup verification passed"
# ----- 上傳至雲端 ----- # 用瀏覽器登入一次 Google 帳號（產生 token）=> 設定 Google Drive(最重要，但只做一次): rclone.conf => 需存在在掛載點($JENKINS_HOME)的本機路徑裡 需認證取得token RCLONE_REMOTE=gdrive # rclone remote name RCLONE_PATH=backup # Google Drive 上的路徑 export RCLONE_CONFIG="$JENKINS_HOME/.config/rclone/rclone.conf" # 傳輸 rclone copy "$ARCHIVE_PATH" "$RCLONE_REMOTE:$RCLONE_PATH" -P # 驗證 #rclone md5sum "$ARCHIVE_PATH" #rclone md5sum "$RCLONE_REMOTE:$RCLONE_PATH/$ARCHIVE" LOCAL_MD5=$(rclone md5sum "$ARCHIVE_PATH" | awk '{print $1}') REMOTE_MD5=$(rclone md5sum "$RCLONE_REMOTE:$RCLONE_PATH/$ARCHIVE" | awk '{print $1}') if [ "$LOCAL_MD5" != "$REMOTE_MD5" ]; then echo "ERROR: MD5 mismatch!" exit 1 fi echo "Cloud upload verification passed" # ===== 清理舊備份（只留最新 KEEP 份）===== cd "$BACKUP_DIR" ls -1t data_source_backup_*.tar.gz | tail -n +$((KEEP+1)) | xargs -r rm -f echo "Old backups cleaned, keeping latest $KEEP files" # ----- 雲端保留最新 N 份 ----- FILES=$(rclone lsf "$RCLONE_REMOTE:$RCLONE_PATH" --files-only | grep '^data_source_backup_.*\.tar\.gz$') echo "$FILES" | sort -r | tail -n +$(($KEEP+1)) | while read -r f; do echo "Deleting old cloud backup: $f" rclone delete "$RCLONE_REMOTE:$RCLONE_PATH/$f" done
